int32_t __stdcall DRLGLEVEL_FixDrlgLevelForLowerKurast(D2DrlgLevelStrc * pLevel) {
    D2DrlgLevelStrc* pSubLevel;
    int nDifficulty;
    int nSubSizeX;
    int nSubSizeY;
    D2DrlgStrc* pDrlgActMisc = pLevel->pDrlg;
    int nParentSizeX = pLevel->sCoordinatesAndSize.WorldSize.x;
    int nYOffset = 0;
    eD2LevelId eLevel = LEVEL_LowerKurast;
    int nSubLevelCount = 5;
    do {
      D2LevelDefsTxt* pLevelDefs;
      pLevelDefs = DATATBLS::LvlTbls::TXT_LevelDefs_GetLine(eLevel);
      nDifficulty = (int)pDrlgActMisc->nDifficulty;
      nSubSizeY = pLevelDefs->SizeY[nDifficulty];
      nSubSizeX = pLevelDefs->SizeX[nDifficulty];
      nYOffset -= nSubSizeY;
      pSubLevel = GetLevelAndAlloc(pDrlgActMisc, eLevel);
      eLevel += LEVEL_RogueEncampment;
      pSubLevel->sCoordinatesAndSize.WorldPosition.x = nParentSizeX / 2 - nSubSizeX / 2 + pLevel->sCoordinatesAndSize.WorldPosition.x;
      nSubLevelCount--;
      pSubLevel->sCoordinatesAndSize.WorldPosition.y = pLevel->sCoordinatesAndSize.WorldPosition.y + nYOffset;
      pSubLevel->sCoordinatesAndSize.WorldSize.x = nSubSizeX;
      pSubLevel->sCoordinatesAndSize.WorldSize.y = nSubSizeY;
    } while (nSubLevelCount);

    return (int32_t)pSubLevel;
}

static void DRLGActMisc_InitAct3(D2DrlgStrc * pDrlg) {
    D2DrlgLevelStrc* pLevel = GetLevelAndAlloc(pDrlg, 0x4b);
    D2LevelDefsTxt* pLevelDefs = DATATBLS::LvlTbls::TXT_LevelDefs_GetLine(LEVEL_KurastDocktown);
    pLevel->sCoordinatesAndSize.WorldPosition.x = pLevelDefs->OffsetX;
    pLevel->sCoordinatesAndSize.WorldPosition.y = pLevelDefs->OffsetY;
    pLevel->sCoordinatesAndSize.WorldSize.x = pLevelDefs->SizeX[pDrlg->nDifficulty];
    pLevel->sCoordinatesAndSize.WorldSize.y = pLevelDefs->SizeY[pDrlg->nDifficulty];
    pLevel = DRLGLEVEL_FixDrlgLevelForSpiderForest(pLevel);
    DRLGLEVEL_FixDrlgLevelForLowerKurast(pLevel);
    DRLGACT_SetWarpConnectionsBetweenTwoAreas(pDrlg, LEVEL_KurastDocktown, 0x53);
    DRLGLEVEL_AllocDrlgLevelFromLevelIdToLevelId(pDrlg, LEVEL_Travincal, LEVEL_KurastDocktown);
}

